contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable {
        require(target != address(c), "target must not be C itself");
        require(target != address(this), "target must not be this");

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        assert(
            reverted
                ? (afterCount == beforeCount && afterBal == beforeBal)
                : (afterCount == beforeCount && beforeBal >= amount && afterBal == beforeBal - amount)
        );
    }

    receive() external payable {}
}

