    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, address target) internal {
        vm.assume(target != address(c));
        vm.assume(target != address(this));
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        bool reverted;
        try c.sendMoney(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
